class KeyValueStore(object):

    def __init__(self):
        self.store = {}

    def set(self, key, value):
        self.store[key] = value
        return True

    def get(self, key):
        if self.store.get(key):
            return self.store[key]
        else:
            return None

    def delete(self, key):
        del self.store[key]

    def increment(self, key):
        if key in self.store:
            self.store[key] += 1
        else:
            self.store[key] = 1
        return self.store[key]

    def decrement(self, key):
        if key in self.store:
            self.store[key] -= 1
        else:
            self.store[key] = -1
        return self.store[key]

    def keys(self):
        return self.store.keys()

